<?php

# @autogenerated
declare(strict_types=1);

use Civi\Lughauth\Features\Access\UserAccessTemporalCode\Domain\ValueObject\Accessor\UserAccessTemporalCodeTempSecondFactorSeedAccessor;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the UserAccessTemporalCodeTempSecondFactorSeedAccessor trait.
 *
 * Covers null default, string/VO assignment via withTempSecondFactorSeed,
 * getTempSecondFactorSeed/tempSecondFactorSeed accessors, and isTempSecondFactorSeedChanged with/without original.
 */
class UserAccessTemporalCodeTempSecondFactorSeedAccessorUnitTest extends TestCase
{
    /**
     * Asserts that withTempSecondFactorSeed creates a new instance with the TempSecondFactorSeed set
     * from a string value, and getTempSecondFactorSeed returns the primitive string.
     */
    public function testWithTempSecondFactorSeedFromString(): void
    {
        // Arrange
        $holder = new ImplWithUserAccessTemporalCodeTempSecondFactorSeedAccessorUnitTest();

        // Act
        $result = $holder->withTempSecondFactorSeed('cyphered://cypher');

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals('****er', $result->getTempSecondFactorSeed());
    }
    /**
     * Asserts that withtempSecondFactorSeed has access to the value object
     * from a string value, and getTempSecondFactorSeed returns the primitive string.
     */
    public function testWithTempSecondFactorSeedFromValueObject(): void
    {
        // Arrange
        $holder = new ImplWithUserAccessTemporalCodeTempSecondFactorSeedAccessorUnitTest();

        // Act
        $result = $holder->withTempSecondFactorSeed('cyphered://cypher');

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals('****er', $result->tempSecondFactorSeed()->value());
    }
    public function testChangedTempSecondFactorSeed(): void
    {
        // Arrange
        $holder = new ImplWithUserAccessTemporalCodeTempSecondFactorSeedAccessorUnitTest();
        $original = $holder->withTempSecondFactorSeed( 'cyphered://cypher');
        $same = $holder->withTempSecondFactorSeed( 'cyphered://cypher');
        $modified = $holder->withTempSecondFactorSeed('cyphered://ocyphered');

        // Act
        $unchanged = $holder->isTempSecondFactorSeedChanged();
        $withSame = $original->isTempSecondFactorSeedChanged( $same );
        $withDiferent = $original->isTempSecondFactorSeedChanged( $modified );

        // Assert
        $this->assertFalse($unchanged);
        $this->assertFalse($withSame);
        $this->assertTrue($withDiferent);
    }
}
class ImplWithUserAccessTemporalCodeTempSecondFactorSeedAccessorUnitTest
{
  use UserAccessTemporalCodeTempSecondFactorSeedAccessor;
}
